            const bitmap_bytes = (((self.columns.len + 7) + 2) / 8);
            var null_bitmap = try reader.read(bitmap_bytes);
            _ = &null_bitmap;
            defer {
            _ = null_bitmap.deinit();
            }
            const cells = try allocator.alloc(SQLDataCell, self.columns.len);
            _ = @memset(cells, SQLDataCell{ .tag = .@"null", .value = .{ .@"null" = 0 } });
            errdefer {
            {
                var idx: usize = 0;
                _ = &idx;
                while ((idx < cells.len)) {
                    _ = cells[@as(usize, @intCast(idx))].deinit();
                    idx = (idx + 1);
                }
                _ = allocator.free(cells);
            }
            }
            const bitmap_offset: usize = 2;
            var i: usize = 0;
            _ = &i;
            while ((i < cells.len)) {
                var value = (&cells[@as(usize, @intCast(i))]);
                _ = &value;
                const byte_pos = cp_shr((bitmap_offset + i), 3);
                const bit_pos = @as(u3, @truncate(((bitmap_offset + i) & 7)));
                const is_null = ((null_bitmap.slice()[@as(usize, @intCast(byte_pos))] & cp_shl((if (comptime @typeInfo(@TypeOf(1)) == .@"enum") cp_cast_int(u8, @intFromEnum(1)) else cp_cast_int(u8, 1)), bit_pos)) != 0);
                if (is_null) {
                    {
                        value.* = SQLDataCell{ .tag = .@"null", .value = .{ .@"null" = 0 } };
                    }
                    i = (i + 1);
                    continue;
                }
                const column = self.columns[@as(usize, @intCast(i))];
                {
                    value.* = try decodeBinaryValue(self.globalObject, column.column_type, column.column_length, self.raw, self.bigint, column.flags.UNSIGNED, column.flags.BINARY, column.character_set, Context, reader);
                }
                value.index = (switch (column.name_or_index) {
.index => |idx| idx,
else => @intCast(i),
});
                value.isIndexedColumn = (switch (column.name_or_index) {
.duplicate => 2,
.index => 1,
.name => 0,
});
                i = (i + 1);
            }
            self.values = cells;
    }
    pub const decode = decoderWrap(Row, decodeInternal).decodeAllocator;
};

